<?php
namespace Modules\BankingMicrofinance\Http\Controllers\Accounting;
use Illuminate\Routing\Controller;use Illuminate\Http\Request;use Modules\BankingMicrofinance\Entities\OfficerTarget;
class OfficerTargetController extends Controller{public function index(){ $targets=OfficerTarget::latest()->paginate(25); return view('bankingmicrofinance::accounting.officer_targets.index',compact('targets'));} public function create(){return view('bankingmicrofinance::accounting.officer_targets.form',['target'=>new OfficerTarget]);} public function store(Request $r){OfficerTarget::create($r->all());return redirect()->route('banking.microfinance.accounting.officer-targets.index');} public function edit(OfficerTarget $officerTarget){return view('bankingmicrofinance::accounting.officer_targets.form',['target'=>$officerTarget]);} public function update(Request $r, OfficerTarget $officerTarget){$officerTarget->update($r->all());return back();} public function destroy(OfficerTarget $officerTarget){$officerTarget->delete();return back();}}
